import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const en = JSON.parse(readFileSync(join(ROOT, "_locales/en/messages.json"), "utf8"));
const entries = Object.entries(en).map(([key, value]) => [key, value.message]);
entries.sort(([a], [b]) => a.localeCompare(b));

const lines = entries.map(([key, message]) => `  ${JSON.stringify(key)}: ${JSON.stringify(message)},`);
const output = [
  "// Generated by tools/build-i18n-fallback.mjs from _locales/en/messages.json. Do not edit by hand.",
  "// The extension itself resolves strings through chrome.i18n; this map is only a",
  "// fallback for contexts where the extension runtime is missing (plain browser, tests).",
  "export const EN_FALLBACK = {",
  ...lines,
  "};",
  "",
].join("\n");

writeFileSync(join(ROOT, "assets/i18n-en.js"), output, "utf8");
console.log(`Wrote assets/i18n-en.js with ${entries.length} keys`);
